require_once __DIR__.'/includes/config.php'; require_once __DIR__.'/includes/auth.php'; sisatRequireRoles([1]);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(isset($_GET['estado'],$_GET['id'])){$id=(int)$_GET['id'];if($id!==(int)$_SESSION['uid']){$nuevo=$_GET['estado']==='ACTIVO'?'ACTIVO':'INACTIVO';$q=$dbh->prepare('UPDATE usuarios_sistema SET estado=?,fecha_actualizacion=NOW() WHERE id=?');$q->execute([$nuevo,$id]);}header('Location: manage-usuarios.php');exit;}
$usuarios=$dbh->query('SELECT u.id,u.nombre_completo,u.usuario,u.correo,u.estado,u.ultimo_acceso,r.nombre AS rol FROM usuarios_sistema u JOIN roles r ON r.id=u.rol_id ORDER BY u.id')->fetchAll(PDO::FETCH_ASSOC);
include __DIR__.'/includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include __DIR__.'/includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><h2 class="title">Gestión de usuarios del sistema</h2><p><a class="btn btn-primary" href="create-usuario.php">Registrar usuario</a></p></div><section class="section"><div class="container-fluid"><div class="panel"><div class="panel-body"><div class="table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Nombre</th><th>Usuario</th><th>Correo</th><th>Perfil</th><th>Estado</th><th>Último acceso</th><th>Acción</th></tr></thead><tbody><?php foreach($usuarios as $u):?><tr><td><?=h($u['nombre_completo'])?></td><td><?=h($u['usuario'])?></td><td><?=h($u['correo'])?></td><td><?=h($u['rol'])?></td><td><?=h($u['estado'])?></td><td><?=h($u['ultimo_acceso'])?></td><td><a class="btn btn-xs btn-info" href="edit-usuario.php?id=<?=(int)$u['id']?>">Editar</a> <?php if((int)$u['id']!==(int)$_SESSION['uid']):?><a class="btn btn-xs btn-<?= $u['estado']==='ACTIVO'?'warning':'success' ?>" href="?id=<?=(int)$u['id']?>&estado=<?=$u['estado']==='ACTIVO'?'INACTIVO':'ACTIVO'?>" onclick="return confirm('¿Cambiar estado del usuario?')"><?=$u['estado']==='ACTIVO'?'Desactivar':'Activar'?></a><?php else:?>Usuario actual<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div></section></div></div></div><?php include __DIR__.'/includes/footer.php';?>
